import type { AppState, GameMode, ScreenId } from '../game/AppState';
import type { Settings } from '../data/settings';
import type { TrackDef } from '../data/tracks';
import type { CarPaint } from '../data/paints';

export class UiShell {
  private readonly root: HTMLElement;

  constructor(
    private readonly app: AppState,
    private readonly handlers: {
      onPrimary: () => void;
      onOpenSettings: () => void;
      onQuitToMenu: () => void;
      onResume: () => void;
      onRestart: () => void;
      audio?: {
        menuConfirm: () => void;
        menuCancel: () => void;
        award: () => void;
      };
    },
  ) {
    const el = document.querySelector<HTMLElement>('#ui-shell');
    if (!el) throw new Error('Missing #ui-shell');
    this.root = el;
    this.render();
  }

  showScreen(screen: ScreenId): void {
    if (screen === 'race') {
      this.root.innerHTML = '';
      return;
    }
    this.render();
  }

  render(): void {
    const screen = this.app.screen;
    if (screen === 'race') {
      this.root.innerHTML = '';
      return;
    }
    if (screen === 'settings') {
      this.root.innerHTML = this.settingsHtml();
      this.bindSettings();
      return;
    }
    if (screen === 'paint') {
      this.root.innerHTML = this.paintHtml();
      this.bindPaint();
      return;
    }
    if (screen === 'track') {
      this.root.innerHTML = this.trackHtml();
      this.bindTrack();
      return;
    }
    if (screen === 'mode') {
      this.root.innerHTML = this.modeHtml();
      this.bindMode();
      return;
    }
    if (screen === 'pause') {
      this.root.innerHTML = this.pauseHtml();
      this.bindPause();
      return;
    }
    if (screen === 'results') {
      this.root.innerHTML = this.resultsHtml();
      this.bindResults();
      return;
    }
    if (screen === 'cup-standings') {
      this.root.innerHTML = this.cupHtml();
      this.bindCup();
      return;
    }
    this.root.innerHTML = this.menuHtml();
    this.bindMenu();
  }

  private menuHtml(): string {
    return `
      <section class="screen" data-screen="menu">
        <p class="kicker">VAPOR · POP · ARCADE</p>
        <h1>NEON DRIFT GP</h1>
        <p class="sub">霓虹漂移大奖赛 · 3 赛道竞速</p>
        <div class="btn-col">
          <button class="neon-btn primary" data-act="primary">开始比赛</button>
          <button class="neon-btn" data-act="settings">设置</button>
        </div>
        <p class="sub">WASD 驾驶 · Space 漂移 · Shift 氮气 · R 重开 · Esc 菜单</p>
      </section>
    `;
  }

  private modeHtml(): string {
    const modes: { id: GameMode; title: string; sub: string }[] = [
      { id: 'race', title: '竞速', sub: '玩家 + 3 AI · 3 圈' },
      { id: 'time-trial', title: '计时', sub: '单人刷圈速' },
      { id: 'cup', title: '杯赛', sub: '3 站积分 · 总冠军' },
    ];
    return `
      <section class="screen" data-screen="mode">
        <p class="kicker">SELECT MODE</p>
        <h2>选择模式</h2>
        <div class="mode-row">
          ${modes
            .map(
              (m) =>
                `<button class="choice ${this.app.mode === m.id ? 'selected' : ''}" data-mode="${m.id}">${m.title}<small>${m.sub}</small></button>`,
            )
            .join('')}
        </div>
        <div class="btn-col">
          <button class="neon-btn primary" data-act="primary">下一步</button>
          <button class="neon-btn ghost" data-act="back">返回</button>
        </div>
      </section>
    `;
  }

  private trackHtml(): string {
    const tracks = this.app.availableTracks();
    return `
      <section class="screen" data-screen="track">
        <p class="kicker">SELECT TRACK</p>
        <h2>选择赛道</h2>
        <div class="track-row">
          ${tracks
            .map(
              (t: { def: TrackDef; unlocked: boolean }) =>
                `<button class="choice ${this.app.trackId === t.def.id ? 'selected' : ''}" data-track="${t.def.id}" ${t.unlocked ? '' : 'disabled'}>
                  ${t.def.nameZh} · ${t.def.nameEn}
                  <small>${t.unlocked ? t.def.blurb : '未解锁'}</small>
                </button>`,
            )
            .join('')}
        </div>
        <div class="btn-col">
          <button class="neon-btn primary" data-act="primary">下一步</button>
          <button class="neon-btn ghost" data-act="back">返回</button>
        </div>
      </section>
    `;
  }

  private paintHtml(): string {
    const paints = this.app.availablePaints();
    return `
      <section class="screen" data-screen="paint">
        <p class="kicker">SELECT PAINT</p>
        <h2>选择涂装</h2>
        <div class="paint-row">
          ${paints
            .map(
              (p: { paint: CarPaint; unlocked: boolean }) =>
                `<button class="choice ${this.app.paintId === p.paint.id ? 'selected' : ''}" data-paint="${p.paint.id}" ${p.unlocked ? '' : 'disabled'}>
                  <div class="paint-swatch" style="background:linear-gradient(90deg,${p.paint.body},${p.paint.accent})"></div>
                  ${p.paint.name}
                  <small>${p.unlocked ? '已解锁' : p.paint.unlockHint}</small>
                </button>`,
            )
            .join('')}
        </div>
        <div class="btn-col">
          <button class="neon-btn primary" data-act="primary">开赛</button>
          <button class="neon-btn ghost" data-act="back">返回</button>
        </div>
      </section>
    `;
  }

  private settingsHtml(): string {
    const s = this.app.settings;
    return `
      <section class="screen" data-screen="settings">
        <p class="kicker">SETTINGS</p>
        <h2>设置</h2>
        <div class="settings-list">
          <label>主音量 <input data-set="masterVolume" type="range" min="0" max="1" step="0.05" value="${s.masterVolume}" /></label>
          <label>BGM <input data-set="bgmVolume" type="range" min="0" max="1" step="0.05" value="${s.bgmVolume}" /></label>
          <label>SFX <input data-set="sfxVolume" type="range" min="0" max="1" step="0.05" value="${s.sfxVolume}" /></label>
          <label>画质
            <select data-set="quality">
              <option value="low" ${s.quality === 'low' ? 'selected' : ''}>低</option>
              <option value="medium" ${s.quality === 'medium' ? 'selected' : ''}>中</option>
              <option value="high" ${s.quality === 'high' ? 'selected' : ''}>高</option>
            </select>
          </label>
          <label>难度
            <select data-set="difficulty" ${this.app.hardUnlocked() ? '' : 'data-hard-locked="1"'}>
              <option value="easy" ${s.difficulty === 'easy' ? 'selected' : ''}>简单</option>
              <option value="normal" ${s.difficulty === 'normal' ? 'selected' : ''}>普通</option>
              <option value="hard" ${s.difficulty === 'hard' && this.app.hardUnlocked() ? 'selected' : ''} ${this.app.hardUnlocked() ? '' : 'disabled'}>困难${this.app.hardUnlocked() ? '' : '（杯赛夺冠解锁）'}</option>
            </select>
          </label>
          <label>圈数
            <select data-set="laps">
              <option value="2" ${s.laps === 2 ? 'selected' : ''}>2</option>
              <option value="3" ${s.laps === 3 ? 'selected' : ''}>3</option>
              <option value="5" ${s.laps === 5 ? 'selected' : ''}>5</option>
            </select>
          </label>
          <label>自动油门 <input data-set="autoThrottle" type="checkbox" ${s.autoThrottle ? 'checked' : ''} /></label>
          <label>转向辅助 <input data-set="assistSteer" type="checkbox" ${s.assistSteer ? 'checked' : ''} /></label>
          <label>减少动态 <input data-set="reducedMotion" type="checkbox" ${s.reducedMotion ? 'checked' : ''} /></label>
        </div>
        <div class="btn-col">
          <button class="neon-btn" data-act="reset">重置进度</button>
          <button class="neon-btn primary" data-act="back">完成</button>
        </div>
      </section>
    `;
  }

  private pauseHtml(): string {
    return `
      <section class="screen" data-screen="pause">
        <p class="kicker">PAUSED</p>
        <h2>暂停</h2>
        <div class="btn-col">
          <button class="neon-btn primary" data-act="resume">继续</button>
          <button class="neon-btn" data-act="restart">重开本局</button>
          <button class="neon-btn" data-act="settings">设置</button>
          <button class="neon-btn ghost" data-act="menu">回主菜单</button>
        </div>
      </section>
    `;
  }

  private resultsHtml(): string {
    return `
      <section class="screen" data-screen="results">
        <p class="kicker">RESULTS</p>
        <h2>本局结算</h2>
        <p class="sub" id="results-detail"></p>
        <div class="btn-col">
          <button class="neon-btn primary" data-act="primary">继续</button>
          <button class="neon-btn" data-act="restart">再来一局</button>
          <button class="neon-btn ghost" data-act="menu">主菜单</button>
        </div>
      </section>
    `;
  }

  private cupHtml(): string {
    const pts = this.app.cup.points.slice(0, 3);
    const totals = this.app.cup.totals;
    const playerTotal = totals[0];
    const bestOther = Math.max(totals[1], totals[2], totals[3]);
    const champion = playerTotal >= bestOther ? 'YOU' : ['NOVA', 'PIXEL', 'YUZU'][totals.indexOf(bestOther) - 1] ?? 'RIVAL';
    return `
      <section class="screen" data-screen="cup-standings">
        <p class="kicker">CUP STANDINGS</p>
        <h2>杯赛积分</h2>
        <div class="cup-points">
          ${pts.map((p: number, i: number) => `<div>LEG ${i + 1}<strong>${p}</strong></div>`).join('')}
        </div>
        <p class="sub">总积分 <strong style="color:var(--yellow)">${playerTotal}</strong> · 冠军 <strong style="color:var(--cyan)">${champion}</strong></p>
        <div class="btn-col">
          <button class="neon-btn primary" data-act="primary">回主菜单</button>
        </div>
      </section>
    `;
  }

  private bindMenu(): void {
    this.root.querySelector('[data-act="primary"]')?.addEventListener('click', () => {
      this.app.setScreen('mode');
      this.render();
      this.handlers.audio?.menuConfirm();
    });
    this.root.querySelector('[data-act="settings"]')?.addEventListener('click', () => {
      this.handlers.onOpenSettings();
    });
  }

  private bindMode(): void {
    this.root.querySelectorAll<HTMLElement>('[data-mode]').forEach((el) => {
      el.addEventListener('click', () => {
        this.app.setMode(el.dataset.mode as GameMode);
        this.render();
        this.handlers.audio?.menuConfirm();
      });
    });
    this.root.querySelector('[data-act="primary"]')?.addEventListener('click', () => {
      if (this.app.mode === 'cup') {
        this.handlers.audio?.menuConfirm();
        this.app.startSession();
      } else {
        this.app.setScreen('track');
        this.render();
        this.handlers.audio?.menuConfirm();
      }
    });
    this.root.querySelector('[data-act="back"]')?.addEventListener('click', () => {
      this.app.setScreen('menu');
      this.render();
      this.handlers.audio?.menuCancel();
    });
  }

  private bindTrack(): void {
    this.root.querySelectorAll<HTMLElement>('[data-track]').forEach((el) => {
      el.addEventListener('click', () => {
        if (el.hasAttribute('disabled')) return;
        this.app.selectTrack(el.dataset.track!);
        this.render();
      });
    });
    this.root.querySelector('[data-act="primary"]')?.addEventListener('click', () => {
      this.app.setScreen('paint');
      this.render();
    });
    this.root.querySelector('[data-act="back"]')?.addEventListener('click', () => {
      this.app.setScreen('mode');
      this.render();
    });
  }

  private bindPaint(): void {
    this.root.querySelectorAll<HTMLElement>('[data-paint]').forEach((el) => {
      el.addEventListener('click', () => {
        if (el.hasAttribute('disabled')) return;
        this.app.selectPaint(el.dataset.paint!);
        this.render();
      });
    });
    this.root.querySelector('[data-act="primary"]')?.addEventListener('click', () => {
      this.app.startSession();
    });
    this.root.querySelector('[data-act="back"]')?.addEventListener('click', () => {
      this.app.setScreen('track');
      this.render();
    });
  }

  private bindSettings(): void {
    const apply = (key: string, raw: string, type: string) => {
      if (key === 'masterVolume' || key === 'bgmVolume' || key === 'sfxVolume') {
        this.app.updateSettings({ [key]: Number(raw) } as Partial<Settings>);
      } else if (key === 'quality') {
        this.app.setQuality(raw as Settings['quality']);
      } else if (key === 'difficulty') {
        this.app.setDifficulty(raw as Settings['difficulty']);
      } else if (key === 'laps') {
        this.app.updateSettings({ laps: Number(raw) as Settings['laps'] });
      } else if (type === 'checkbox') {
        this.app.updateSettings({ [key]: raw === 'on' || raw === 'true' } as Partial<Settings>);
      }
    };

    this.root.querySelectorAll<HTMLInputElement>('input[data-set], select[data-set]').forEach((el) => {
      const key = el.dataset.set!;
      const handler = () => {
        if (el instanceof HTMLInputElement && el.type === 'checkbox') {
          apply(key, el.checked ? 'true' : 'false', 'checkbox');
        } else {
          apply(key, el.value, el instanceof HTMLSelectElement ? 'select' : 'range');
        }
      };
      el.addEventListener('change', handler);
      el.addEventListener('input', () => {
        if (el instanceof HTMLInputElement && el.type === 'range') handler();
      });
    });

    this.root.querySelector('[data-act="back"]')?.addEventListener('click', () => {
      this.handlers.onPrimary();
    });
    this.root.querySelector('[data-act="reset"]')?.addEventListener('click', () => {
      this.app.resetProgress();
      this.render();
    });
  }

  private bindPause(): void {
    this.root.querySelector('[data-act="resume"]')?.addEventListener('click', () => {
      this.handlers.onResume();
    });
    this.root.querySelector('[data-act="restart"]')?.addEventListener('click', () => {
      this.handlers.onRestart();
    });
    this.root.querySelector('[data-act="settings"]')?.addEventListener('click', () => {
      this.app.setScreen('settings');
      this.render();
    });
    this.root.querySelector('[data-act="menu"]')?.addEventListener('click', () => {
      this.handlers.onQuitToMenu();
    });
  }

  private bindResults(): void {
    this.root.querySelector('[data-act="primary"]')?.addEventListener('click', () => {
      if (this.app.mode === 'cup' && !this.app.cup.finished) {
        this.app.nextCupLeg();
      } else {
        this.handlers.onQuitToMenu();
      }
    });
    this.root.querySelector('[data-act="restart"]')?.addEventListener('click', () => {
      this.handlers.onRestart();
    });
    this.root.querySelector('[data-act="menu"]')?.addEventListener('click', () => {
      this.handlers.onQuitToMenu();
    });
  }

  private bindCup(): void {
    this.root.querySelector('[data-act="primary"]')?.addEventListener('click', () => {
      this.handlers.onQuitToMenu();
    });
  }

  setResultsDetail(text: string): void {
    const el = this.root.querySelector('#results-detail');
    if (el) el.textContent = text;
  }
}
