export class AudioSystem {
  private context: AudioContext | null = null;
  private unlocked = false;
  muted = false;
  private masterVolume = 0.8;
  private bgmVolume = 0.7;
  private sfxVolume = 0.85;
  private engineOsc: OscillatorNode | null = null;
  private engineGain: GainNode | null = null;
  private engineFilter: BiquadFilterNode | null = null;
  private bgmOsc: OscillatorNode | null = null;
  private bgmGain: GainNode | null = null;
  private buffers = new Map<string, AudioBuffer>();
  private samplePaths: Record<string, string> = {
    award: 'audio/award.ogg',
    go: 'audio/go.ogg',
  };

  constructor() {
    const unlock = () => {
      void this.unlock();
      window.removeEventListener('pointerdown', unlock);
      window.removeEventListener('keydown', unlock);
    };
    window.addEventListener('pointerdown', unlock, { once: true });
    window.addEventListener('keydown', unlock, { once: true });
    void this.preloadSamples();
  }

  private async preloadSamples(): Promise<void> {
    const injected = (globalThis as { __NDGP_AUDIO__?: Record<string, string> }).__NDGP_AUDIO__;
    for (const [name, path] of Object.entries(this.samplePaths)) {
      try {
        const url = injected?.[path] ?? path;
        const res = await fetch(url);
        if (!res.ok) continue;
        const buf = await res.arrayBuffer();
        this.pending ??= new Map();
        this.pending.set(name, buf);
      } catch {
        /* offline / file:// — procedural fallback */
      }
    }
    if (this.context) await this.decodePending();
  }

  private pending: Map<string, ArrayBuffer> | null = null;

  private async decodePending(): Promise<void> {
    if (!this.context || !this.pending) return;
    for (const [name, raw] of this.pending) {
      try {
        const audio = await this.context.decodeAudioData(raw.slice(0));
        this.buffers.set(name, audio);
      } catch {
        /* keep procedural */
      }
    }
  }

  private playSample(name: string, fallback: () => void): void {
    if (!this.context || this.muted) return;
    const buf = this.buffers.get(name);
    if (!buf) {
      fallback();
      return;
    }
    const src = this.context.createBufferSource();
    const gain = this.context.createGain();
    gain.gain.value = this.sfxVolume * this.masterVolume;
    src.buffer = buf;
    src.connect(gain).connect(this.context.destination);
    src.start();
  }

  async unlock(): Promise<void> {
    if (this.unlocked) return;
    const AudioContextClass =
      window.AudioContext ||
      (window as unknown as { webkitAudioContext?: typeof AudioContext }).webkitAudioContext;
    if (!AudioContextClass) return;
    this.context = new AudioContextClass();
    await this.context.resume();
    this.unlocked = true;
    this.startEngine();
    this.startBgm();
    await this.decodePending();
  }

  setVolumes(master: number, bgm: number, sfx: number): void {
    this.masterVolume = master;
    this.bgmVolume = bgm;
    this.sfxVolume = sfx;
    if (this.engineGain && this.context) {
      this.engineGain.gain.value = this.muted ? 0 : 0.03 * this.masterVolume;
    }
    if (this.bgmGain && this.context) {
      const target = this.muted ? 0 : 0.018 * this.bgmVolume * this.masterVolume;
      this.bgmGain.gain.setTargetAtTime(target, this.context.currentTime, 0.15);
    }
    if (!this.bgmOsc) this.startBgm();
  }

  private startBgm(): void {
    if (!this.context || this.bgmOsc) return;
    const ctx = this.context;
    const osc = ctx.createOscillator();
    const gain = ctx.createGain();
    const filter = ctx.createBiquadFilter();
    osc.type = 'triangle';
    osc.frequency.value = 110;
    filter.type = 'lowpass';
    filter.frequency.value = 600;
    gain.gain.value = this.muted ? 0 : 0.018 * this.bgmVolume * this.masterVolume;
    osc.connect(filter).connect(gain).connect(ctx.destination);
    osc.start();
    this.bgmOsc = osc;
    this.bgmGain = gain;
    // slow vapor detune
    const lfo = ctx.createOscillator();
    const lfoGain = ctx.createGain();
    lfo.frequency.value = 0.07;
    lfoGain.gain.value = 4;
    lfo.connect(lfoGain).connect(osc.frequency);
    lfo.start();
  }

  private startEngine(): void {
    if (!this.context || this.engineOsc) return;
    const ctx = this.context;
    const osc = ctx.createOscillator();
    const gain = ctx.createGain();
    const filter = ctx.createBiquadFilter();
    osc.type = 'sawtooth';
    osc.frequency.value = 60;
    filter.type = 'lowpass';
    filter.frequency.value = 400;
    gain.gain.value = 0.0;
    osc.connect(filter).connect(gain).connect(ctx.destination);
    osc.start();
    this.engineOsc = osc;
    this.engineGain = gain;
    this.engineFilter = filter;
  }

  updateEngine(speed01: number, drifting: boolean, boosting: boolean, active: boolean): void {
    if (!this.context || !this.engineOsc || !this.engineGain || !this.engineFilter) return;
    if (this.muted) {
      this.engineGain.gain.value = 0;
      return;
    }
    const now = this.context.currentTime;
    const base = 55 + speed01 * 90 + (boosting ? 30 : 0);
    this.engineOsc.frequency.setTargetAtTime(base, now, 0.05);
    this.engineFilter.frequency.setTargetAtTime(300 + speed01 * 1200, now, 0.08);
    const target = active ? (0.03 + speed01 * 0.045) * this.masterVolume : 0.0;
    this.engineGain.gain.setTargetAtTime(target, now, 0.1);
    this.engineFilter.Q.value = drifting ? 4 : 1;
  }

  lap(): void {
    this.blip(520, 780, 0.15, 'triangle');
    window.setTimeout(() => this.blip(780, 1040, 0.18, 'triangle'), 120);
  }

  boost(): void {
    this.blip(200, 900, 0.2, 'sawtooth');
  }

  impact(): void {
    this.blip(120, 60, 0.12, 'square');
  }

  private blip(from: number, to: number, duration: number, type: OscillatorType): void {
    if (!this.context || this.muted || this.context.state !== 'running') return;
    const oscillator = this.context.createOscillator();
    const gain = this.context.createGain();
    const now = this.context.currentTime;
    const peak = 0.06 * this.sfxVolume * this.masterVolume;
    oscillator.type = type;
    oscillator.frequency.setValueAtTime(from, now);
    oscillator.frequency.exponentialRampToValueAtTime(Math.max(40, to), now + duration);
    gain.gain.setValueAtTime(0.0001, now);
    gain.gain.exponentialRampToValueAtTime(Math.max(0.0002, peak), now + 0.02);
    gain.gain.exponentialRampToValueAtTime(0.0001, now + duration);
    oscillator.connect(gain).connect(this.context.destination);
    oscillator.start(now);
    oscillator.stop(now + duration + 0.05);
  }

  countdownBeep(): void {
    this.blip(440, 440, 0.08, 'square');
  }

  goBeep(): void {
    this.playSample('go', () => this.blip(660, 1200, 0.22, 'triangle'));
  }

  menuConfirm(): void {
    this.blip(520, 780, 0.08, 'triangle');
  }

  menuCancel(): void {
    this.blip(420, 280, 0.08, 'triangle');
  }

  award(): void {
    this.playSample('award', () => {
      this.blip(520, 780, 0.12, 'triangle');
      window.setTimeout(() => this.blip(780, 1040, 0.18, 'triangle'), 100);
    });
  }

  pickup(index: number): void {
    this.blip(320 + index * 20, 700 + index * 20, 0.14, 'triangle');
  }

  dispose(): void {
    try {
      this.engineOsc?.stop();
    } catch {
      /* already stopped */
    }
    try {
      this.bgmOsc?.stop();
    } catch {
      /* already stopped */
    }
    this.engineOsc = null;
    this.engineGain = null;
    this.engineFilter = null;
    this.bgmOsc = null;
    this.bgmGain = null;
    void this.context?.close();
    this.context = null;
  }
}
