export type QualityLevel = 'low' | 'medium' | 'high';
export type Difficulty = 'easy' | 'normal' | 'hard';

export type Settings = {
  masterVolume: number;
  bgmVolume: number;
  sfxVolume: number;
  quality: QualityLevel;
  difficulty: Difficulty;
  autoThrottle: boolean;
  assistSteer: boolean;
  laps: 2 | 3 | 5;
  reducedMotion: boolean;
};

export type Unlocks = {
  paints: string[];
  tracks: string[];
  hardDifficulty: boolean;
  bestLaps: Record<string, number>;
  boostCount: number;
  cupWins: number;
  cupFinishes: number;
  goldLaps: string[];
  normalCupWins: number;
};

export const DEFAULT_SETTINGS: Settings = {
  masterVolume: 0.8,
  bgmVolume: 0.7,
  sfxVolume: 0.85,
  quality: 'high',
  difficulty: 'normal',
  autoThrottle: false,
  assistSteer: true,
  laps: 3,
  reducedMotion: false,
};

export const DEFAULT_UNLOCKS: Unlocks = {
  paints: ['nova'],
  tracks: ['neon-loop'],
  hardDifficulty: false,
  bestLaps: {},
  boostCount: 0,
  cupWins: 0,
  cupFinishes: 0,
  goldLaps: [],
  normalCupWins: 0,
};

/** Gold-lap thresholds (seconds) for time-trial unlock path. */
export const GOLD_LAP_SECONDS: Record<string, number> = {
  'neon-loop': 78,
  'sunset-pier': 88,
  'void-grid': 72,
};

const STORAGE_KEY = 'neon-drift-v1';

export type SaveBlob = {
  settings: Settings;
  unlocks: Unlocks;
};

export function loadSave(): SaveBlob {
  try {
    const raw = localStorage.getItem(STORAGE_KEY);
    if (!raw) {
      return { settings: { ...DEFAULT_SETTINGS }, unlocks: structuredClone(DEFAULT_UNLOCKS) };
    }
    const parsed = JSON.parse(raw) as Partial<SaveBlob>;
    return {
      settings: { ...DEFAULT_SETTINGS, ...(parsed.settings ?? {}) },
      unlocks: { ...structuredClone(DEFAULT_UNLOCKS), ...(parsed.unlocks ?? {}) },
    };
  } catch {
    return { settings: { ...DEFAULT_SETTINGS }, unlocks: structuredClone(DEFAULT_UNLOCKS) };
  }
}

export function saveSave(blob: SaveBlob): void {
  try {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(blob));
  } catch {
    // storage may be blocked; non-fatal
  }
}

export function resetSave(): SaveBlob {
  const blob = { settings: { ...DEFAULT_SETTINGS }, unlocks: structuredClone(DEFAULT_UNLOCKS) };
  saveSave(blob);
  return blob;
}

export function isPaintUnlocked(unlocks: Unlocks, paintId: string): boolean {
  return unlocks.paints.includes(paintId) || paintId === 'nova';
}

export function isTrackUnlocked(unlocks: Unlocks, trackId: string): boolean {
  return unlocks.tracks.includes(trackId) || trackId === 'neon-loop';
}

export function applyUnlockProgress(
  unlocks: Unlocks,
  event:
    | { type: 'cup-finish' }
    | { type: 'cup-win'; difficulty: Difficulty }
    | { type: 'boost' }
    | { type: 'gold-lap'; trackId: string; bestLap: number }
    | { type: 'track-clear'; trackId: string },
): Unlocks {
  const next: Unlocks = structuredClone(unlocks);
  if (event.type === 'cup-finish') next.cupFinishes += 1;
  if (event.type === 'cup-win') {
    next.cupWins += 1;
    if (event.difficulty === 'normal' || event.difficulty === 'hard') {
      next.normalCupWins += 1;
    }
  }
  if (event.type === 'boost') next.boostCount += 1;
  if (event.type === 'gold-lap') {
    const prev = next.bestLaps[event.trackId];
    if (!(prev > 0) || event.bestLap < prev) next.bestLaps[event.trackId] = event.bestLap;
    const gold = GOLD_LAP_SECONDS[event.trackId];
    if (gold && event.bestLap <= gold && !next.goldLaps.includes(event.trackId)) {
      next.goldLaps.push(event.trackId);
    }
  }
  if (event.type === 'track-clear') {
    const order = ['neon-loop', 'sunset-pier', 'void-grid'];
    const idx = order.indexOf(event.trackId);
    if (idx >= 0 && idx + 1 < order.length) {
      const unlockId = order[idx + 1];
      if (!next.tracks.includes(unlockId)) next.tracks.push(unlockId);
    }
    if (!next.tracks.includes(event.trackId)) next.tracks.push(event.trackId);
  }

  // time-trial bronze-ish: any recorded lap unlocks that track
  for (const id of Object.keys(next.bestLaps)) {
    if (!next.tracks.includes(id)) next.tracks.push(id);
  }

  if (next.cupFinishes >= 1 && !next.paints.includes('pixel')) next.paints.push('pixel');
  if (next.boostCount >= 15 && !next.paints.includes('yuzu')) next.paints.push('yuzu');
  if ((next.normalCupWins >= 1 || next.goldLaps.includes('sunset-pier')) && !next.paints.includes('blush')) {
    next.paints.push('blush');
  }
  if (next.normalCupWins >= 1) next.hardDifficulty = true;

  return next;
}

export function qualityFlags(q: QualityLevel): {
  maxDpr: number;
  shadows: boolean;
  bloom: boolean;
} {
  if (q === 'low') return { maxDpr: 1, shadows: false, bloom: false };
  if (q === 'medium') return { maxDpr: 1.5, shadows: true, bloom: true };
  return { maxDpr: 2, shadows: true, bloom: true };
}
