export type CarPaint = {
  id: string;
  name: string;
  body: string;
  accent: string;
  emissive: string;
  unlockHint: string;
  unlock: {
    kind: 'default' | 'cup-finish' | 'cup-win' | 'boost-count' | 'gold-lap';
    value?: number;
    trackId?: string;
  };
};

