import {
  applyUnlockProgress,
  isPaintUnlocked,
  isTrackUnlocked,
  loadSave,
  resetSave,
  saveSave,
  type Difficulty,
  type QualityLevel,
  type Settings,
  type Unlocks,
} from '../data/settings';
import { PAINTS, getPaint, type CarPaint } from '../data/paints';
import { TRACKS, cupOrder, getTrack, type TrackDef } from '../data/tracks';

export type GameMode = 'race' | 'time-trial' | 'cup';

export type ScreenId =
  | 'boot'
  | 'menu'
  | 'mode'
  | 'track'
  | 'paint'
  | 'settings'
  | 'pause'
  | 'results'
  | 'cup-standings'
  | 'race';

export type CupState = {
  leg: number;
  /** player points per leg (length 3) */
  points: number[];
  /** cumulative points by racer index: [player, ai0, ai1, ai2] */
  totals: number[];
  finished: boolean;
};

export type SessionConfig = {
  mode: GameMode;
  trackId: string;
  paintId: string;
  laps: number;
  difficulty: Difficulty;
};

export type AppEvents = {
  onScreenChange: (screen: ScreenId) => void;
  onSessionStart: (cfg: SessionConfig) => void;
  onSettingsChange: (settings: Settings) => void;
  onUnlocksChange: (unlocks: Unlocks) => void;
};

export class AppState {
  screen: ScreenId = 'boot';
  mode: GameMode = 'race';
  trackId: string = TRACKS[0].id;
  paintId: string = PAINTS[0].id;
  cup: CupState = { leg: 0, points: [0, 0, 0], totals: [0, 0, 0, 0], finished: false };
  settings: Settings;
  unlocks: Unlocks;

  constructor(private readonly events: AppEvents) {
    const save = loadSave();
    this.settings = save.settings;
    this.unlocks = save.unlocks;
  }

  setScreen(screen: ScreenId): void {
    if (this.screen === screen) return;
    this.screen = screen;
    this.events.onScreenChange(screen);
  }

  get track(): TrackDef {
    return getTrack(this.trackId);
  }

  get paint(): CarPaint {
    return getPaint(this.paintId);
  }

  availableTracks(): { def: TrackDef; unlocked: boolean }[] {
    return TRACKS.map((def) => ({
      def,
      unlocked: isTrackUnlocked(this.unlocks, def.id) || this.mode === 'cup',
    }));
  }

  availablePaints(): { paint: CarPaint; unlocked: boolean }[] {
    return PAINTS.map((paint) => ({
      paint,
      unlocked: isPaintUnlocked(this.unlocks, paint.id),
    }));
  }

  selectTrack(id: string): void {
    this.trackId = id;
  }

  selectPaint(id: string): void {
    if (!isPaintUnlocked(this.unlocks, id) && id !== 'nova') return;
    this.paintId = id;
  }

  setMode(mode: GameMode): void {
    this.mode = mode;
  }

  updateSettings(patch: Partial<Settings>): void {
    this.settings = { ...this.settings, ...patch };
    saveSave({ settings: this.settings, unlocks: this.unlocks });
    this.events.onSettingsChange(this.settings);
  }

  resetProgress(): void {
    const blob = resetSave();
    this.settings = blob.settings;
    this.unlocks = blob.unlocks;
    this.events.onSettingsChange(this.settings);
    this.events.onUnlocksChange(this.unlocks);
  }

  sessionConfig(): SessionConfig {
    const laps = this.settings.laps;
    return {
      mode: this.mode,
      trackId: this.mode === 'cup' ? cupOrder()[this.cup.leg % 3].id : this.trackId,
      paintId: this.paintId,
      laps,
      difficulty: this.settings.difficulty,
    };
  }

  startSession(): void {
    if (this.mode === 'cup') {
      this.cup = { leg: 0, points: [0, 0, 0], totals: [0, 0, 0, 0], finished: false };
    }
    this.events.onSessionStart(this.sessionConfig());
    this.setScreen('race');
  }

  restartSession(): void {
    this.events.onSessionStart(this.sessionConfig());
    this.setScreen('race');
  }

  /** Points for finishing position (1-based). */
  private pointsFor(position: number): number {
    const table = [10, 8, 6, 4];
    return table[position - 1] ?? 2;
  }

  completeRace(result: {
    position: number;
    bestLap: number;
    trackId: string;
    boostHits: number;
    /** finish order indices: player is 0, AI 1..3 */
    order?: number[];
  }): void {
    let unlocks = this.unlocks;
    if (result.boostHits > 0) {
      for (let i = 0; i < result.boostHits; i += 1) {
        unlocks = applyUnlockProgress(unlocks, { type: 'boost' });
      }
    }
    if (result.bestLap > 0) {
      unlocks = applyUnlockProgress(unlocks, {
        type: 'gold-lap',
        trackId: result.trackId,
        bestLap: result.bestLap,
      });
    }
    if (this.mode !== 'time-trial') {
      unlocks = applyUnlockProgress(unlocks, {
        type: 'track-clear',
        trackId: result.trackId,
      });
    }

    if (this.mode === 'cup') {
      const idx = this.cup.leg;
      const order = result.order ?? [0, 1, 2, 3];
      const pointsTable = this.pointsFor.bind(this);
      order.forEach((racer, placeIdx) => {
        const pts = pointsTable(placeIdx + 1);
        this.cup.totals[racer] = (this.cup.totals[racer] ?? 0) + pts;
        if (racer === 0) this.cup.points[idx] = pts;
      });
      const done = idx >= 2;
      this.cup.leg = done ? idx : idx + 1;
      this.cup.finished = done;
      if (done) {
        unlocks = applyUnlockProgress(unlocks, { type: 'cup-finish' });
        const playerTotal = this.cup.totals[0];
        const bestOther = Math.max(this.cup.totals[1], this.cup.totals[2], this.cup.totals[3]);
        if (playerTotal >= bestOther) {
          unlocks = applyUnlockProgress(unlocks, {
            type: 'cup-win',
            difficulty: this.settings.difficulty,
          });
        }
      }
      this.unlocks = unlocks;
      saveSave({ settings: this.settings, unlocks });
      this.events.onUnlocksChange(unlocks);
      this.setScreen(done ? 'cup-standings' : 'results');
      return;
    }

    this.unlocks = unlocks;
    saveSave({ settings: this.settings, unlocks });
    this.events.onUnlocksChange(unlocks);
    this.setScreen('results');
  }

  nextCupLeg(): void {
    if (this.cup.finished) {
      this.setScreen('menu');
      return;
    }
    this.events.onSessionStart(this.sessionConfig());
    this.setScreen('race');
  }

  hardUnlocked(): boolean {
    return this.unlocks.hardDifficulty;
  }

  setDifficulty(d: Difficulty): void {
    if (d === 'hard' && !this.unlocks.hardDifficulty) return;
    this.updateSettings({ difficulty: d });
  }

  setQuality(q: QualityLevel): void {
    this.updateSettings({ quality: q });
  }
}
