export type TrackTheme = {
  fog: string;
  accent: string;
  skyBottom: string;
  skyMid: string;
  skyTop: string;
  landmark: 'arch' | 'tower' | 'sun';
  palette: 'city' | 'pier' | 'void';
  ground: string;
  edgeA: string;
  edgeB: string;
};

export type TrackDef = {
  id: 'neon-loop' | 'sunset-pier' | 'void-grid';
  nameZh: string;
  nameEn: string;
  blurb: string;
  controlPoints: [number, number][];
  roadHalfWidth: number;
  theme: TrackTheme;
  cupIndex: 0 | 1 | 2;
  difficulty: 1 | 2 | 3;
};

