export function getTrack(id: string): TrackDef {
  return TRACKS.find((t) => t.id === id) ?? TRACKS[0];
}

export function cupOrder(): TrackDef[] {
  return [...TRACKS].sort((a, b) => a.cupIndex - b.cupIndex);
}
