import * as THREE from 'three';
import { InputController } from '../core/InputController';
import { Loop } from '../core/Loop';
import { createRenderer, resizeRenderer } from '../core/Renderer';
import {
  Car,
  DEFAULT_CAR_TUNING,
  type CarPaint,
  type CarTuning,
} from '../entities/Car';
import { Track } from '../entities/Track';
import { AudioSystem } from '../systems/AudioSystem';
import { ChaseCamera } from '../systems/ChaseCamera';
import { DebugTools, type DebugTuning } from '../systems/DebugTools';
import { Hud } from '../systems/Hud';
import { RaceSystem, type RaceState } from '../systems/RaceSystem';
import { UiShell } from '../systems/UiShell';
import { AppState, type SessionConfig } from './AppState';
import { getPaint } from '../data/paints';
import { qualityFlags } from '../data/settings';
import { animateVaporWorld, buildVaporWorld } from '../world/World';

const AI_PAINT_DEFS: CarPaint[] = [
  { body: '#2dfff3', accent: '#ff2d95', emissive: '#2dfff3', name: 'NOVA' },
  { body: '#ffe600', accent: '#b84dff', emissive: '#ffe600', name: 'PIXEL' },
  { body: '#b84dff', accent: '#2dfff3', emissive: '#b84dff', name: 'YUZU' },
];

function paintToCarPaint(p: { body: string; accent: string; emissive: string; name: string }): CarPaint {
  return { body: p.body, accent: p.accent, emissive: p.emissive, name: p.name };
}

export class Game {
  private readonly renderer: THREE.WebGLRenderer;
  private readonly scene = new THREE.Scene();
  private readonly camera = new THREE.PerspectiveCamera(58, 1, 0.1, 500);
  private readonly input: InputController;
  private track: Track;
  private cars: Car[] = [];
  private player!: Car;
  private race: RaceSystem;
  private readonly audio = new AudioSystem();
  private readonly hud = new Hud();
  private readonly chase: ChaseCamera;
  private world: THREE.Group;
  private readonly app: AppState;
  private readonly ui: UiShell;
  private readonly loop = new Loop(
    (delta, elapsed) => this.update(delta, elapsed),
    () => this.render(),
  );

  private readonly tuning: DebugTuning = {
    ...DEFAULT_CAR_TUNING,
    cameraLag: 4.5,
    exposure: 1.1,
    maxDpr: 2,
  };

  private readonly debugTools: DebugTools;
  private frame = 0;
  private elapsed = 0;
  private pausedForScreenshot = false;
  private reducedMotion = false;
  private paused = false;
  private lastPlayerLap = 0;
  private accumulator = 0;
  private readonly fixedDt = 1 / 60;
  private boostHits = 0;
  private lastBoosting = false;
  private sessionMode: 'race' | 'time-trial' | 'cup' = 'race';
  private sessionLaps = 3;

  constructor(private readonly canvas: HTMLCanvasElement) {
    this.renderer = createRenderer(canvas);
    this.renderer.toneMappingExposure = this.tuning.exposure;

    const stick = document.querySelector<HTMLElement>('#touch-stick');
    const knob = document.querySelector<HTMLElement>('#touch-knob');
    const boostBtn = document.querySelector<HTMLElement>('#boost-button');
    const driftBtn = document.querySelector<HTMLElement>('#drift-button');
    this.input = new InputController(stick, knob, boostBtn, driftBtn);

    this.debugTools = new DebugTools(this.tuning, () => {
      this.renderer.toneMappingExposure = this.tuning.exposure;
      resizeRenderer(this.renderer, this.camera, this.tuning.maxDpr);
    });

    this.app = new AppState({
      onScreenChange: (screen) => {
        this.ui.showScreen(screen);
        this.paused = screen === 'pause' || screen === 'settings' || screen === 'menu';
        document.querySelector('#hud')?.toggleAttribute('hidden', screen !== 'race' && screen !== 'pause');
      },
      onSessionStart: (cfg) => this.buildSession(cfg),
      onSettingsChange: (settings) => {
        this.reducedMotion = settings.reducedMotion;
        this.applyQuality(settings.quality);
        this.audio.setVolumes(settings.masterVolume, settings.bgmVolume, settings.sfxVolume);
      },
      onUnlocksChange: () => {
        this.ui.render();
      },
    });

    this.ui = new UiShell(this.app, {
      onPrimary: () => {
        const from = this.app.screen;
        if (from === 'settings' && this.paused) {
          this.app.setScreen('pause');
          this.ui.render();
          return;
        }
        this.app.setScreen('menu');
        this.ui.render();
      },
      onOpenSettings: () => {
        this.app.setScreen('settings');
        this.ui.render();
      },
      onQuitToMenu: () => {
        this.paused = true;
        this.app.setScreen('menu');
        this.ui.render();
      },
      onResume: () => {
        this.paused = false;
        this.app.setScreen('race');
        this.ui.showScreen('race');
      },
      onRestart: () => {
        this.paused = false;
        this.app.restartSession();
        this.ui.showScreen('race');
      },
      audio: {
        menuConfirm: () => this.audio.menuConfirm(),
        menuCancel: () => this.audio.menuCancel(),
        award: () => this.audio.award(),
      },
    });

    this.track = new Track(this.app.track);
    this.race = new RaceSystem(this.track, [], 3);
    this.world = buildVaporWorld(
      { curve: this.track.curve, halfWidth: this.track.roadHalfWidth },
      this.track.def.theme,
    );
    this.chase = new ChaseCamera(this.camera, this.tuning.cameraLag);

    this.buildSession({
      mode: 'race',
      trackId: this.app.trackId,
      paintId: this.app.paintId,
      laps: this.app.settings.laps,
      difficulty: this.app.settings.difficulty,
    });
    this.applyQuality(this.app.settings.quality);
    this.audio.setVolumes(
      this.app.settings.masterVolume,
      this.app.settings.bgmVolume,
      this.app.settings.sfxVolume,
    );
    this.reducedMotion = this.app.settings.reducedMotion;

    this.app.setScreen('menu');
    this.ui.render();
    this.installTestHooks();
    this.publishDiagnostics();
    (window as unknown as { __GAME_SCENE__?: THREE.Scene }).__GAME_SCENE__ = this.scene;
  }

  start(): void {
    this.loop.start();
  }

  dispose(): void {
    this.loop.stop();
    this.input.dispose();
    this.audio.dispose();
    this.debugTools.dispose();
    this.track.dispose();
    this.renderer.dispose();
    window.__THREE_GAME_DIAGNOSTICS__ = undefined;
    window.__THREE_GAME_TEST_HOOKS__ = undefined;
  }

  private applyQuality(quality: 'low' | 'medium' | 'high'): void {
    const flags = qualityFlags(quality);
    this.tuning.maxDpr = flags.maxDpr;
    resizeRenderer(this.renderer, this.camera, flags.maxDpr);
    // bloom proxy: exposure + fog already present; shadows via key light
    this.world.traverse((obj) => {
      if (obj instanceof THREE.DirectionalLight) obj.castShadow = flags.shadows;
    });
  }

  private buildSession(cfg: SessionConfig): void {
    this.sessionMode = cfg.mode;
    this.sessionLaps = cfg.laps;
    this.boostHits = 0;
    this.lastBoosting = false;

    // rebuild track + world
    this.scene.remove(this.track.group);
    this.track.dispose();
    this.scene.remove(this.world);
    this.track = new Track(cfg.trackId);
    this.world = buildVaporWorld(
      { curve: this.track.curve, halfWidth: this.track.roadHalfWidth },
      this.track.def.theme,
    );
    this.scene.fog = new THREE.FogExp2(this.track.def.theme.fog, 0.0045);
    this.scene.add(this.track.group);
    this.scene.add(this.world);

    // rebuild cars
    for (const car of this.cars) this.scene.remove(car.group);
    this.cars = [];

    const playerPaint = paintToCarPaint(getPaint(cfg.paintId));
    playerPaint.name = 'YOU';
    this.player = new Car(this.track, 0, playerPaint, true, this.tuning);
    this.cars.push(this.player);

    const showAi = cfg.mode !== 'time-trial';
    if (showAi) {
      const aiTuning: CarTuning = {
        ...this.tuning,
        maxSpeed: cfg.difficulty === 'easy' ? 38 : cfg.difficulty === 'hard' ? 50 : 44,
        boostSpeed: cfg.difficulty === 'easy' ? 52 : cfg.difficulty === 'hard' ? 68 : 60,
        accel: cfg.difficulty === 'easy' ? 28 : cfg.difficulty === 'hard' ? 38 : 34,
      };
      AI_PAINT_DEFS.forEach((paint, i) => {
        this.cars.push(new Car(this.track, i + 1, paint, false, aiTuning));
      });
    }

    this.race = new RaceSystem(this.track, this.cars, cfg.laps, cfg.difficulty);
    this.race.onCountdownBeep = () => this.audio.countdownBeep();
    this.race.onGo = () => this.audio.goBeep();
    if (cfg.mode === 'time-trial') {
      this.race.setTimeTrial(true);
    }

    for (const car of this.cars) this.scene.add(car.group);
    this.chase.snapTo(this.player.position, this.player.heading);
    this.lastPlayerLap = 0;
    this.paused = false;
    this.hud.update(this.snapshotHud(this.race.getState()));
    this.publishDiagnostics();
  }

  private update(delta: number, elapsed: number): void {
    this.frame += 1;
    if (this.pausedForScreenshot) {
      this.publishDiagnostics();
      return;
    }

    const intent = this.input.readIntent();
    if (intent.restart && this.app.screen === 'race') {
      this.app.restartSession();
      this.ui.showScreen('race');
      this.hud.flashCountdown?.();
      return;
    }
    if (intent.pause) {
      if (this.app.screen === 'race' && this.race.phase === 'racing') {
        this.paused = true;
        this.app.setScreen('pause');
        this.ui.render();
      } else if (this.app.screen === 'pause') {
        this.paused = false;
        this.app.setScreen('race');
        this.ui.showScreen('race');
      }
    }

    if (this.app.screen !== 'race' && this.app.screen !== 'pause') {
      // idle render behind menus
      this.chase.update(
        0,
        this.player.position,
        this.player.heading,
        this.player.speed,
        false,
        false,
      );
      this.render();
      this.publishDiagnostics();
      return;
    }

    resizeRenderer(this.renderer, this.camera, this.tuning.maxDpr);
    this.elapsed += this.paused ? 0 : delta;

    const simDelta = this.paused ? 0 : delta;
    this.accumulator = Math.min(this.accumulator + simDelta, 0.1);
    while (this.accumulator >= this.fixedDt) {
      const raceActive = this.race.phase === 'racing' && !this.paused;
      if (raceActive) {
        this.applyIntentToPlayer(intent);
      } else {
        // countdown / finished: freeze player input so the car cannot jump the start
        this.player.controls.throttle = 0;
        this.player.controls.steer = 0;
        this.player.controls.brake = false;
        this.player.controls.drift = false;
        this.player.controls.boost = false;
      }
      for (const car of this.cars) car.update(this.fixedDt, raceActive);
      this.race.update(this.fixedDt);
      const prevBoosting = this.lastBoosting;
      const boostingNow = this.player.controls.boost && this.player.boost > 0.2;
      if (boostingNow && !prevBoosting) {
        this.boostHits += 1;
        this.audio.boost();
        this.flashBoost(true);
      }
      this.lastBoosting = boostingNow;
      this.accumulator -= this.fixedDt;
    }

    if (this.player.lap > this.lastPlayerLap && this.race.phase === 'racing') {
      this.lastPlayerLap = this.player.lap;
      const improved = this.player.bestLap === this.player.lastLap;
      this.race.flashMessage(
        improved ? `BEST ${formatLap(this.player.lastLap)}` : `LAP ${formatLap(this.player.lastLap)}`,
      );
      this.audio.lap();
      this.chase.addTrauma(0.25);
    }

    const animElapsed = this.reducedMotion ? 0 : elapsed;
    animateVaporWorld(this.world, animElapsed);

    const boostActive =
      this.player.controls.boost && this.player.boost > 0 && this.player.controls.throttle > 0.1;
    this.chase.update(
      this.paused ? 0 : delta,
      this.player.position,
      this.player.heading,
      this.player.speed,
      this.player.drifting,
      boostActive,
    );
    if (this.player.collisionFlash > 0.9) {
      this.chase.addTrauma(0.15);
      this.audio.impact();
    }

    this.updateJuice(boostActive);

    this.world.traverse((obj) => {
      if (obj instanceof THREE.DirectionalLight && obj.userData?.shadowKey) {
        obj.target.position.copy(this.player.position);
        obj.target.updateMatrixWorld();
        obj.position.copy(this.player.position).add(new THREE.Vector3(40, 60, 20));
      }
    });

    const state = this.race.getState();
    this.audio.updateEngine(
      THREE.MathUtils.clamp(this.player.speed / 50, 0, 1),
      this.player.drifting,
      boostActive && this.player.boost > 0,
      this.race.phase !== 'finished' && !this.paused,
    );
    this.hud.update(this.snapshotHud(state));
    this.publishDiagnostics();

    if (state.phase === 'finished' && this.app.screen === 'race') {
      this.finishSession(state);
    }
  }

  private finishSession(state: RaceState): void {
    const position = state.playerPosition;
    this.audio.award();
    const order = state.standings.map((s) => s.index);
    this.ui.setResultsDetail(
      `名次 ${position}/${state.standings.length} · 最佳圈 ${formatLap(state.playerBestLap || this.player.bestLap)} · 氮气 ${this.boostHits}`,
    );
    this.app.completeRace({
      position,
      bestLap: state.playerBestLap || this.player.bestLap,
      trackId: this.track.def.id,
      boostHits: this.boostHits,
      order,
    });
    this.ui.render();
  }

  private updateJuice(boostActive: boolean): void {
    const speed01 = THREE.MathUtils.clamp(this.player.speed / 50, 0, 1);
    const lines = document.querySelector<HTMLElement>('#speed-lines');
    const chroma = document.querySelector<HTMLElement>('#chroma');
    const flash = document.querySelector<HTMLElement>('#boost-flash');
    if (!lines || !chroma || !flash) return;
    const on = speed01 > 0.35 || this.player.drifting;
    lines.classList.toggle('on', on && !this.reducedMotion);
    lines.classList.toggle('boost', boostActive && !this.reducedMotion);
    chroma.classList.toggle('on', (this.player.drifting || boostActive) && !this.reducedMotion);
    flash.classList.toggle('on', boostActive && !this.reducedMotion);
    if (on) lines.style.opacity = String(0.25 + speed01 * 0.75);
  }

  private flashBoost(on: boolean): void {
    const flash = document.querySelector<HTMLElement>('#boost-flash');
    if (flash) flash.classList.toggle('on', on && !this.reducedMotion);
  }

  private applyIntentToPlayer(intent: ReturnType<InputController['readIntent']>): void {
    const auto = this.app.settings.autoThrottle;
    this.player.controls.throttle = auto ? Math.max(intent.throttle, 0.55) : intent.throttle;
    let steer = intent.steer;
    if (this.app.settings.assistSteer && Math.abs(steer) > 0.01) {
      steer = THREE.MathUtils.clamp(steer * 1.05, -1, 1);
    }
    this.player.controls.steer = steer;
    this.player.controls.brake = intent.brake;
    this.player.controls.drift = intent.drift;
    this.player.controls.boost = intent.boost;
  }

  private snapshotHud(s: RaceState) {
    return {
      speedKph: this.player.speed * 3.6,
      boost: this.player.boost,
      drifting: this.player.drifting,
      lap: s.playerLap,
      totalLaps: s.totalLaps,
      position: this.sessionMode === 'time-trial' ? 1 : s.playerPosition,
      fieldSize: this.sessionMode === 'time-trial' ? 1 : this.cars.length,
      raceTime: s.raceTime,
      currentLapTime: this.player.lapTime,
      bestLap: s.playerBestLap,
      lastLap: s.playerLastLap,
      countdown: s.phase === 'countdown' ? Math.max(1, Math.ceil(s.countdown - 0.5)) : 0,
      message: s.message,
      phase: s.phase,
      standings:
        this.sessionMode === 'time-trial'
          ? [{ name: 'YOU', isPlayer: true, lap: s.playerLap, paint: this.player.paint.body }]
          : s.standings.map((row) => ({
              name: row.name,
              isPlayer: row.isPlayer,
              lap: row.lap,
              paint: row.paint,
            })),
    };
  }

  private render(): void {
    this.renderer.render(this.scene, this.camera);
  }

  private installTestHooks(): void {
    window.__THREE_GAME_TEST_HOOKS__ = {
      seed: (value: number) => {
        void value;
      },
      setState: (name: string) => {
        if (name !== 'active-play' && name !== 'complete' && name !== 'title') {
          throw new Error(`Unknown test state: ${name}`);
        }
        if (name === 'title') {
          this.app.setScreen('menu');
          this.ui.render();
          this.render();
          this.publishDiagnostics();
          return { state: name };
        }
        this.app.setScreen('race');
        this.ui.showScreen('race');
        this.paused = false;
        this.race.reset();
        if (name === 'active-play') {
          this.race.phase = 'racing';
          this.race.countdown = 0;
          this.race.raceTime = 12.4;
          this.player.controls.throttle = 1;
          this.player.controls.steer = 0.25;
          this.player.controls.drift = true;
          this.player.boost = 0.8;
          this.player.position.copy(this.track.pointAt(0.15, -1.5));
          const s = this.track.getSample(Math.floor(0.15 * 400));
          this.player.heading = Math.atan2(s.tangent.x, s.tangent.z);
          this.player.velocity.copy(this.player.getForward().multiplyScalar(32));
          this.player.speed = 32;
          this.player.drifting = true;
          this.chase.snapTo(this.player.position, this.player.heading);
          for (const car of this.cars) car.update(this.fixedDt, true);
        }
        if (name === 'complete') {
          this.race.phase = 'racing';
          this.race.countdown = 0;
          for (const car of this.cars) car.lap = this.sessionLaps;
          for (const car of this.cars) car.unwrappedProgress = this.sessionLaps + 0.05;
          this.race.update(this.fixedDt);
          this.finishSession(this.race.getState());
        }
        this.hud.update(this.snapshotHud(this.race.getState()));
        this.render();
        this.publishDiagnostics();
        return { state: name };
      },
      setPausedForScreenshot: (paused: boolean) => {
        this.pausedForScreenshot = paused;
      },
      setReducedMotion: (enabled: boolean) => {
        this.reducedMotion = enabled;
        this.render();
        this.publishDiagnostics();
      },
      hideDebugUi: (hidden: boolean) => {
        this.debugTools.setHidden(hidden);
      },
    };
  }

  private publishDiagnostics(): void {
    const info = this.renderer.info;
    window.__THREE_GAME_DIAGNOSTICS__ = {
      frame: this.frame,
      elapsed: this.elapsed,
      score: this.player.lap,
      targetScore: this.race.totalLaps,
      complete: this.race.phase === 'finished',
      screen: this.app.screen,
      track: this.track.def.id,
      player: {
        position: {
          x: this.player.position.x,
          y: this.player.position.y,
          z: this.player.position.z,
        },
        speed: this.player.speed,
        drifting: this.player.drifting,
        boost: this.player.boost,
      },
      renderer: {
        calls: info.render.calls,
        triangles: info.render.triangles,
        geometries: info.memory.geometries,
        textures: info.memory.textures,
      },
      canvas: {
        clientWidth: this.canvas.clientWidth,
        clientHeight: this.canvas.clientHeight,
        width: this.canvas.width,
        height: this.canvas.height,
        dpr: Math.min(window.devicePixelRatio || 1, this.tuning.maxDpr),
      },
    };
  }
}

function formatLap(seconds: number): string {
  return `${seconds.toFixed(2)}s`;
}
